draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // draw phone
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-75, 100, 150);
  ctx.stroke();

  // draw receiver
  ctx.beginPath();
  ctx.rect(W/2-20, H/2-100, 40, 50);
  ctx.stroke();

  // draw dialer
  ctx.beginPath();
  ctx.arc(W/2, H/2, 40, 0, 2*Math.PI);
  ctx.stroke();

  // draw numbers
  ctx.font = '30px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('8', W/2-35+20*Math.sin(t), H/2+20);
  ctx.fillText('8', W/2-10+20*Math.sin(t), H/2+20);
  ctx.fillText('6', W/2+15+20*Math.sin(t), H/2+20);

  ctx.restore();
}
